-- Full-text search over articles (SQLite FTS5).
-- Text is normalised for Arabic before indexing (tashkeel/tatweel removed; alef forms, ya/alef-maqsura,
-- ta-marbuta/ha, hamza-on-waw/ya and Arabic-Indic digits unified). lib/search.ts applies the SAME mapping
-- to the user's query, so keep the two lists identical if you ever change one.
-- The replacements are split into nested sub-selects because SQLite limits how deeply one expression can nest.
-- Triggers keep the index in sync on every insert / update / delete of an article.

CREATE VIRTUAL TABLE IF NOT EXISTS `articles_fts` USING fts5(
  id UNINDEXED,
  title,
  subtitle,
  caption,
  author,
  category,
  tokenize = 'unicode61 remove_diacritics 2',
  prefix = '2 3'
);

CREATE TRIGGER IF NOT EXISTS `articles_fts_ai` AFTER INSERT ON `articles`
BEGIN
  INSERT INTO articles_fts (id, title, subtitle, caption, author, category)
  SELECT id, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(title, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS title, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(subtitle, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS subtitle, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(caption, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS caption, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(author, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS author, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(category, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS category FROM (
SELECT id, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(title, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS title, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(subtitle, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS subtitle, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(caption, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS caption, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(author, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS author, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(category, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS category FROM (
SELECT id, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(title, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS title, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(subtitle, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS subtitle, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(caption, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS caption, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(author, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS author, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(category, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS category FROM (
SELECT id, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(title, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS title, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(subtitle, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS subtitle, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(caption, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS caption, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(author, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS author, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(category, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS category FROM (
SELECT new.id AS id, new.title AS title, COALESCE(new.subtitle, '') AS subtitle, COALESCE(new.caption, '') AS caption, COALESCE(new.author_name, '') AS author, new.category AS category
)
)
)
);
END;

CREATE TRIGGER IF NOT EXISTS `articles_fts_ad` AFTER DELETE ON `articles`
BEGIN
  DELETE FROM articles_fts WHERE id = old.id;
END;

CREATE TRIGGER IF NOT EXISTS `articles_fts_au` AFTER UPDATE OF id, title, subtitle, caption, author_name, category ON `articles`
BEGIN
  DELETE FROM articles_fts WHERE id = old.id;
  INSERT INTO articles_fts (id, title, subtitle, caption, author, category)
  SELECT id, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(title, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS title, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(subtitle, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS subtitle, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(caption, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS caption, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(author, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS author, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(category, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS category FROM (
SELECT id, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(title, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS title, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(subtitle, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS subtitle, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(caption, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS caption, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(author, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS author, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(category, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS category FROM (
SELECT id, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(title, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS title, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(subtitle, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS subtitle, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(caption, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS caption, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(author, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS author, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(category, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS category FROM (
SELECT id, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(title, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS title, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(subtitle, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS subtitle, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(caption, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS caption, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(author, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS author, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(category, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS category FROM (
SELECT new.id AS id, new.title AS title, COALESCE(new.subtitle, '') AS subtitle, COALESCE(new.caption, '') AS caption, COALESCE(new.author_name, '') AS author, new.category AS category
)
)
)
);
END;

-- Index every article that already exists.
DELETE FROM articles_fts;
INSERT INTO articles_fts (id, title, subtitle, caption, author, category)
SELECT id, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(title, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS title, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(subtitle, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS subtitle, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(caption, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS caption, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(author, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS author, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(category, char(1635), char(51)), char(1636), char(52)), char(1637), char(53)), char(1638), char(54)), char(1639), char(55)), char(1640), char(56)), char(1641), char(57)) AS category FROM (
SELECT id, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(title, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS title, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(subtitle, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS subtitle, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(caption, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS caption, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(author, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS author, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(category, char(1649), char(1575)), char(1609), char(1610)), char(1577), char(1607)), char(1572), char(1608)), char(1574), char(1610)), char(1632), char(48)), char(1633), char(49)), char(1634), char(50)) AS category FROM (
SELECT id, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(title, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS title, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(subtitle, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS subtitle, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(caption, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS caption, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(author, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS author, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(category, char(1619), ''), char(1620), ''), char(1621), ''), char(1648), ''), char(1600), ''), char(1571), char(1575)), char(1573), char(1575)), char(1570), char(1575)) AS category FROM (
SELECT id, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(title, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS title, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(subtitle, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS subtitle, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(caption, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS caption, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(author, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS author, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(category, char(1611), ''), char(1612), ''), char(1613), ''), char(1614), ''), char(1615), ''), char(1616), ''), char(1617), ''), char(1618), '') AS category FROM (
SELECT id, title, COALESCE(subtitle, '') AS subtitle, COALESCE(caption, '') AS caption, COALESCE(author_name, '') AS author, category FROM articles
)
)
)
);
